"""Focused tests for deterministic live-DOM discovery helpers."""

from __future__ import annotations

import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from discovery import _build_manifest, _events_to_findings, _is_expected_link_endpoint, _is_expected_navigation, _is_replay_link_endpoint, _manifest_coverage, _manifest_selector_for_qid, _should_assert_visible_after_click, state_fingerprint


class DiscoveryHelperTests(unittest.TestCase):
    def test_state_fingerprint_changes_when_visible_qids_change(self):
        a = {
            "url": "http://example.test",
            "bodyText": "ready",
            "interactives": [{"qid": "a:b", "visible": True, "enabled": True, "ariaExpanded": "", "text": "Open"}],
            "dialogs": [],
        }
        b = {
            "url": "http://example.test",
            "bodyText": "ready dialog",
            "interactives": [
                {"qid": "a:b", "visible": True, "enabled": True, "ariaExpanded": "", "text": "Open"},
                {"qid": "a:dialog:button", "visible": True, "enabled": True, "ariaExpanded": "", "text": "OK"},
            ],
            "dialogs": [{"qid": "a:dialog"}],
        }
        self.assertNotEqual(state_fingerprint(a), state_fingerprint(b))

    def test_generated_manifest_uses_only_data_qid_selectors(self):
        manifest = _build_manifest("http://127.0.0.1:8775/discovery_defects.html", [{
            "url": "http://127.0.0.1:8775/discovery_defects.html",
            "title": "fixture",
            "interactives": [
                {"qid": "fixture:ok", "visible": True, "enabled": True, "title": "OK", "qsAction": "OK"},
                {"qid": "", "visible": True, "enabled": True, "title": "", "qsAction": ""},
            ],
        }])
        interactions = [
            interaction
            for surface in manifest["surfaces"]
            for element in surface["elements"]
            for interaction in element["interactions"]
        ]
        self.assertEqual(len(interactions), 1)
        self.assertEqual(interactions[0]["target"], "[data-qid='fixture:ok']")
        self.assertEqual(interactions[0]["assert_timing"], "before")
        self.assertEqual(manifest["base_url"], "http://127.0.0.1:8775")
        self.assertEqual(manifest["surfaces"][0]["path"], "/discovery_defects.html")
        self.assertTrue(manifest["surfaces"][0]["isolate_interactions"])
        self.assertNotIn("nth-child", str(manifest))
        self.assertNotIn(".missing", str(manifest))

    def test_generated_manifest_marks_external_links(self):
        manifest = _build_manifest("https://grahama.co", [{
            "url": "https://grahama.co",
            "title": "fixture",
            "interactives": [
                {
                    "qid": "hero:link:repo",
                    "visible": True,
                    "enabled": True,
                    "title": "Repo",
                    "qsAction": "HERO_OPEN_REPO",
                    "href": "https://github.com/grahama1970/agent-skills",
                    "tag": "a",
                },
            ],
        }])
        interaction = manifest["surfaces"][0]["elements"][0]["interactions"][0]
        self.assertTrue(interaction["allow_external_navigation"])
        self.assertEqual(interaction["action"], "wait")
        self.assertIn("without launching", interaction["description"])

    def test_generated_manifest_marks_static_file_links(self):
        manifest = _build_manifest("https://grahama.co/resume", [{
            "url": "https://grahama.co/resume",
            "title": "fixture",
            "interactives": [
                {
                    "qid": "resume:link:docx",
                    "visible": True,
                    "enabled": True,
                    "title": "DOCX",
                    "qsAction": "RESUME_DOWNLOAD_DOCX",
                    "href": "https://grahama.co/resume.docx",
                    "tag": "a",
                },
            ],
        }])
        item = {
            "qid": "resume:link:docx",
            "tag": "a",
            "href": "https://grahama.co/resume.docx",
        }
        interaction = manifest["surfaces"][0]["elements"][0]["interactions"][0]
        self.assertTrue(_is_expected_link_endpoint(item, "https://grahama.co"))
        self.assertTrue(_is_expected_navigation(item, "https://grahama.co/resume", "https://grahama.co/resume"))
        self.assertEqual(interaction["action"], "wait")
        self.assertIn("static link endpoint", interaction["description"])

    def test_generated_manifest_marks_internal_links_as_replay_endpoints(self):
        manifest = _build_manifest("https://grahama.co", [{
            "url": "https://grahama.co",
            "title": "fixture",
            "interactives": [
                {
                    "qid": "nav:link:resume",
                    "visible": True,
                    "enabled": True,
                    "title": "Resume",
                    "qsAction": "NAV_RESUME",
                    "href": "https://grahama.co/resume",
                    "tag": "a",
                },
            ],
        }])
        item = {
            "qid": "nav:link:resume",
            "tag": "a",
            "href": "https://grahama.co/resume",
        }
        interaction = manifest["surfaces"][0]["elements"][0]["interactions"][0]
        self.assertTrue(_is_replay_link_endpoint(item))
        self.assertFalse(_is_expected_link_endpoint(item, "https://grahama.co"))
        self.assertEqual(interaction["action"], "wait")
        self.assertIn("without navigating away", interaction["description"])

    def test_generated_manifest_keeps_root_url_and_groups_routes(self):
        manifest = _build_manifest("https://grahama.co", [
            {
                "url": "https://grahama.co",
                "title": "root",
                "interactives": [
                    {"qid": "hero:action:repo", "visible": True, "enabled": True, "title": "Repo", "qsAction": "HERO_OPEN_REPO"},
                ],
            },
            {
                "url": "https://grahama.co/resume",
                "title": "resume",
                "interactives": [
                    {"qid": "resume:link:pdf", "visible": True, "enabled": True, "title": "PDF", "qsAction": "RESUME_DOWNLOAD_PDF"},
                ],
            },
        ])
        self.assertEqual(manifest["base_url"], "https://grahama.co")
        surfaces = {surface["path"]: surface for surface in manifest["surfaces"]}
        self.assertEqual(set(surfaces), {"/", "/resume"})
        self.assertEqual(surfaces["/"]["elements"][0]["name"], "hero-action-repo")
        self.assertEqual(surfaces["/resume"]["elements"][0]["name"], "resume-link-pdf")
        self.assertTrue(all(surface["isolate_interactions"] for surface in manifest["surfaces"]))

    def test_manifest_selector_for_qid_uses_qid_target(self):
        self.assertEqual(_manifest_selector_for_qid("fixture:ok"), "[data-qid='fixture:ok']")

    def test_generated_manifest_does_not_assert_visibility_after_close(self):
        self.assertFalse(_should_assert_visible_after_click({"qid": "fixture:close-dialog", "text": "Close"}))
        self.assertTrue(_should_assert_visible_after_click({"qid": "fixture:open-dialog", "text": "Open"}))

    def test_manifest_coverage_reads_qid_targets_only(self):
        manifest = {
            "surfaces": [{
                "elements": [{
                    "interactions": [
                        {"target": "[data-qid='fixture:covered']"},
                        {"target": ".class-fallback"},
                    ]
                }]
            }]
        }
        self.assertEqual(_manifest_coverage(manifest), {"[data-qid='fixture:covered']"})

    def test_console_and_network_events_become_findings(self):
        findings = _events_to_findings("run-1", [
            {"method": "Runtime.exceptionThrown", "params": {"exceptionDetails": {"text": "Uncaught"}}},
            {"method": "Network.responseReceived", "params": {"response": {"status": 404, "url": "http://example.test/missing"}}},
        ], {"qid": "fixture:throws", "selector": "[data-qid='fixture:throws']", "tag": "button"}, "state-1")
        self.assertEqual([item["finding_kind"] for item in findings], ["console_exception", "network_failure"])

    def test_anchor_navigation_is_expected_not_drift(self):
        item = {
            "qid": "nav:link:resume",
            "selector": "[data-qid='nav:link:resume']",
            "tag": "a",
            "href": "https://grahama.co/resume",
            "qsAction": "NAV_RESUME",
        }
        self.assertTrue(_is_expected_navigation(item, "https://grahama.co", "https://grahama.co/resume"))
        button = {"qid": "fixture:url-drift", "tag": "button", "qsAction": "FIXTURE_URL_DRIFT"}
        self.assertFalse(_is_expected_navigation(button, "http://example.test", "http://example.test?drift=1"))


